package com.cdac.cssip.user.repository; import com.cdac.cssip.user.entity.User; import com.cdac.cssip.common.enums.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface UserRepository extends JpaRepository<User,Long>{Optional<User> findByCdacId(String cdacId); Optional<User> findByEmail(String email); boolean existsByEmail(String email); boolean existsByCdacId(String cdacId); List<User> findByStatus(UserStatus status); List<User> findByRole(Role role); List<User> findByFullNameContainingIgnoreCase(String k); @Query("select u from User u where u.role=:role and (lower(u.fullName) like lower(concat('%',:k,'%')) or lower(u.cdacId) like lower(concat('%',:k,'%')) or lower(u.email) like lower(concat('%',:k,'%'))) ") List<User> search(@Param("role") Role role,@Param("k") String k);}
